import 'dart:convert';
import 'advanced_theme_model.dart';
Map<String,Object?> importThemeDocument(String text){if(utf8.encode(text).length>32768)throw const FormatException('Theme file too large');if(text.trimLeft().startsWith('<'))return {'kind':'legacy-layout','value':legacyLayoutXml(text)};final raw=jsonDecode(text);if(raw is Map&&raw['version']==1)return {'kind':'legacy-personal','value':legacyPersonalTheme(raw).toJson()};return {'kind':'advanced','value':AdvancedTheme.fromJson(raw).toJson()};}
/// Canonical v1 exports remain data-only; declarations, entities, namespaces and extra markup fail closed.
Map<String,Object> legacyLayoutXml(String text){if(utf8.encode(text).length>16384||RegExp(r'<!|<\?|&').hasMatch(text))throw const FormatException('Unsupported XML');final match=RegExp(r'^\s*<PrimeCareLayout\s+([^<>]*)>\s*<Theme\s+([^<>]*)/\s*>\s*<Shell\s+([^<>]*)/\s*>\s*</PrimeCareLayout>\s*$').firstMatch(text);if(match==null)throw const FormatException('Invalid layout XML');
 Map<String,String> attrs(String raw,List<String> keys){final values=<String,String>{};final pattern=RegExp(r'''([A-Za-z]+)\s*=\s*(?:"([^"]*)"|'([^']*)')''');for(final m in pattern.allMatches(raw)){final key=m[1]!;if(values.containsKey(key)||!keys.contains(key))throw const FormatException('Unknown XML field');values[key]=m[2]??m[3]!;}if(raw.replaceAll(pattern,'').trim().isNotEmpty||values.length!=keys.length)throw const FormatException('Invalid XML attributes');return values;}
 final root=attrs(match[1]!,['version']),theme=attrs(match[2]!,['preset','accent']),shell=attrs(match[3]!,['sidebar','navigation','density','contentWidth']);if(root['version']!='1'||!['default','light','dark'].contains(theme['preset'])||theme['accent']!=''&&!RegExp(r'^#[0-9a-fA-F]{6}$').hasMatch(theme['accent']!)||!['left','right'].contains(shell['sidebar'])||!['expanded','compact'].contains(shell['navigation'])||!['comfortable','compact'].contains(shell['density'])||!RegExp(r'^\d{2,3}$').hasMatch(shell['contentWidth']!))throw const FormatException('Invalid layout XML setting');final width=int.parse(shell['contentWidth']!);if(width<75||width>100)throw const FormatException('Invalid layout width');return {'version':1,'theme':theme['preset']!,'accent':theme['accent']!.toLowerCase(),'sidebar':shell['sidebar']!,'navigation':shell['navigation']!,'density':shell['density']!,'contentWidth':width};
}
